import{_ as t,o,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"篇947｜反掠夺天道规则·规则十三——跨位面操作严格报备","description":"","frontmatter":{"title":"篇947｜反掠夺天道规则·规则十三——跨位面操作严格报备","no":947,"module":5,"tags":["天道规则","规则十三","跨位面","报备制","因果自律"],"related":["28-跨位面锚点连接","915-跨位面操作报备制","948-先观测后有限干涉"]},"headers":[],"relativePath":"zh/947_模块5-规则十三-跨位面操作严格报备.md","filePath":"zh/947_模块5-规则十三-跨位面操作严格报备.md"}'),r={name:"zh/947_模块5-规则十三-跨位面操作严格报备.md"};function i(n,a,h,u,s,q){return o(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="篇947-反掠夺天道规则·规则十三——跨位面操作严格报备" tabindex="-1">篇947｜反掠夺天道规则·规则十三——跨位面操作严格报备 <a class="header-anchor" href="#篇947-反掠夺天道规则·规则十三——跨位面操作严格报备" aria-label="Permalink to &quot;篇947｜反掠夺天道规则·规则十三——跨位面操作严格报备&quot;">​</a></h1><blockquote><p>所属模块：模块五·文明终极定型典藏篇｜对标地基：文档28｜系列：反掠夺天道规则大全</p></blockquote><h2 id="引言-去别人的宇宙-先打报告" tabindex="-1">引言：去别人的宇宙，先打报告 <a class="header-anchor" href="#引言-去别人的宇宙-先打报告" aria-label="Permalink to &quot;引言：去别人的宇宙，先打报告&quot;">​</a></h2><p>因果自律公理最容易被突破的口子，是跨位面。旧宇宙的强者们一个念头穿越位面、随手改造下界、把别界当试验田，从来无人过问。天道规则十三把这道口子焊死：任何强者、任何文明工程，凡跨位面操作——无论是去开发、去援助、去研究、去撤退——必须事先向锚点监督委员会严格报备，说明目的、手段、预计因果影响，获批后方可执行。报备不是不信任强者，而是不让任何一位强者替两个位面的众生私自写历史。</p><p>六大顶层公理在此集中约束强者的外延行为：因果自律公理是本规则的直接来源；万族共和公理决定被干涉位面的众生也是&quot;主人&quot;，不容外人替其做主；反掠夺主义公理否定&quot;跨位面当殖民地&quot;；集体升维公理要求跨位面目的须是共赢而非单方面取利；法则优先公理让&quot;报备—审批—留痕&quot;程序由法则先行钉死。</p><p>更须点出新增的公理六·众生全员无限均等法则——锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。这一公理从根上改写了掠夺的意义：旧宇宙资源与大道有限，故被迫掠夺内卷；衡元宙人人自带无限本源，掠夺失去意义。本条天道规则所立，正是这一&quot;无限本源、掠夺无意义&quot;新秩序的法则护栏。</p><h2 id="一、规则内容-报备的三要件" tabindex="-1">一、规则内容：报备的三要件 <a class="header-anchor" href="#一、规则内容-报备的三要件" aria-label="Permalink to &quot;一、规则内容：报备的三要件&quot;">​</a></h2><ol><li><strong>目的报备</strong>：写明跨位面操作的目的——援助、开发、研究、撤离、追捕逃犯，分类登记</li><li><strong>手段报备</strong>：写明将使用的力量层级、可能动用的法则、预计持续时间</li><li><strong>因果影响报备</strong>：评估对被干涉位面、对本文明、对跨位面因果网络的潜在扰动，附缓解方案</li></ol><p>紧急追捕掠夺逃犯等情形允许&quot;先执行后补报&quot;，但须在最短时间内补报并接受追溯审查。</p><h2 id="二、法理依据" tabindex="-1">二、法理依据 <a class="header-anchor" href="#二、法理依据" aria-label="Permalink to &quot;二、法理依据&quot;">​</a></h2><ul><li><strong>他者主权论证</strong>：《跨位面锚点连接》（文档28）指出，每个位面都是独立因果主体，外人无主权擅自介入，即对该位面众生的掠夺</li><li><strong>因果连锁论证</strong>：跨位面操作的因果影响远超位面内，一次轻率干预可能在别界掀起文明倒退，故须事前评估</li><li><strong>防滥用论证</strong>：旧宇宙&quot;大神游历下界&quot;的浪漫叙事背后，常是对弱小位面的隐性支配，报备制把这种支配摆上台面</li></ul><h2 id="三、执行机制" tabindex="-1">三、执行机制 <a class="header-anchor" href="#三、执行机制" aria-label="Permalink to &quot;三、执行机制&quot;">​</a></h2><ul><li>阿赖耶网络设&quot;跨位面报备接口&quot;，一切跨位面锚点调用必经此接口</li><li>未报备的跨位面操作，网络自动识别并冻结其位面穿梭能力，直至补报</li><li>报备审批由锚点监督委员会牵头，相关位面代表、意识信息族因果分析师共同会签</li><li>执行全程留痕，事后须提交&quot;因果影响复盘报告&quot;，核验当初评估是否准确</li></ul><h2 id="四、违反后果" tabindex="-1">四、违反后果 <a class="header-anchor" href="#四、违反后果" aria-label="Permalink to &quot;四、违反后果&quot;">​</a></h2><ul><li><strong>轻度</strong>：报备不全、评估粗疏，限期补正</li><li><strong>中度</strong>：未报备擅自跨位面操作，冻结位面穿梭能力，转转化程序</li><li><strong>重度</strong>：以跨位面操作为名行掠夺之实——下界开采、殖民、收割，按规则三、规则十八（根除轮回收割）从重处置</li></ul><h2 id="五、监督主体" tabindex="-1">五、监督主体 <a class="header-anchor" href="#五、监督主体" aria-label="Permalink to &quot;五、监督主体&quot;">​</a></h2><p>阿赖耶网络+多层监督的跨位面报备接口为第一层；锚点监督委员会审批与事后复盘为第二层；被干涉位面代表对&quot;是否欢迎、干预是否过度&quot;有最终发言权为第三层；共生法院审理跨位面掠夺案件为第四层。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li>反能级浪费：避免跨位面误操作引发的连锁灾难，节省巨量修复能量</li><li>反掠夺：把&quot;跨位面当后花园&quot;的旧习立法禁止；公理六下人人自带基础无限之力，有限资源的掠夺从根上失去意义</li><li>唐罗上限对比：唐罗式强者一念跨界、下界自生自灭；衡元宙跨界先报备，下界代表有否决权</li><li>万族全覆盖：被干涉位面的一切生灵（含星球意识、未开化族群）均在被保护之列</li><li>超多元全开放：跨位面操作报备制随世界观无限扩容自动适用新位面，不设例外</li></ul><p>跨位面报备制在紧急情形下的弹性，也需讲清。追捕掠夺逃犯、拦截轮回收割系统、救援将被吞噬的弱小位面，这三类情形允许&quot;先执行后补报&quot;。但弹性不是免死金牌：事后补报时须提交完整的因果影响复盘，若发现&quot;紧急&quot;只是借口，事后照样按未报备处置。报备制要的是责任，不是流程；真正紧急的救援不会因为走流程而延误，真正该防的是拿&quot;紧急&quot;当万能钥匙。这套弹性设计，让报备制既有牙齿，又不至于在真正的灾难面前迂腐误事。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>跨位面报备，是因果自律公理在宇宙尺度的第一道闸门。它保证了：强者的脚再长，也不能不敲门就走进别人的宇宙。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./28-跨位面锚点连接">28-跨位面锚点连接</a> · <a href="./915_模块5-第十四条-跨位面操作报备制">915-跨位面操作报备制</a> · <a href="./946_模块5-规则十二-杜绝大材小用">946-规则十二-杜绝大材小用</a> · <a href="./948_模块5-规则十四-先观测后有限干涉">948-规则十四-先观测后有限干涉</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',24)])])}const c=t(r,[["render",i]]);export{d as __pageData,c as default};
